// Pinia Store定义
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';

// Composition API风格（推荐）
export const useUserStore = defineStore('user', () => {
  // State
  const name = ref('John');
  const age = ref(25);
  const token = ref(localStorage.getItem('token') || '');

  // Getters
  const isAdult = computed(() => age.value >= 18);
  const userInfo = computed(() => `${name.value}, ${age.value}岁`);

  // Actions
  async function login(credentials) {
    const res = await fetch('/api/login', {
      method: 'POST',
      body: JSON.stringify(credentials)
    });
    const data = await res.json();
    token.value = data.token;
    localStorage.setItem('token', data.token);
  }

  function updateAge(newAge) {
    age.value = newAge;
  }

  function $reset() {
    name.value = 'John';
    age.value = 25;
    token.value = '';
  }

  return { name, age, token, isAdult, userInfo, login, updateAge, $reset };
});

// Options API风格
export const useCounterStore = defineStore('counter', {
  state: () => ({ count: 0 }),
  getters: {
    double: (state) => state.count * 2
  },
  actions: {
    increment() { this.count++; }
  }
});

// 组件中使用
import { useUserStore } from '@/stores/user';
import { storeToRefs } from 'pinia';

export default {
  setup() {
    const userStore = useUserStore();
    const { name, isAdult } = storeToRefs(userStore); // 解构保持响应性
    const { login } = userStore; // 方法不需要storeToRefs

    return { name, isAdult, login };
  }
};

// Vue Router 路由守卫
import { createRouter, createWebHistory } from 'vue-router';

const router = createRouter({
  history: createWebHistory(),
  routes: [
    {
      path: '/dashboard',
      component: Dashboard,
      beforeEnter: (to, from) => {
        // 路由独享守卫
        if (!isAuthenticated()) return '/login';
      }
    }
  ]
});

// 全局前置守卫
router.beforeEach((to, from) => {
  if (to.meta.requiresAuth && !isAuthenticated()) {
    return { path: '/login', query: { redirect: to.fullPath } };
  }
});

// 全局后置钩子
router.afterEach((to, from) => {
  document.title = to.meta.title || 'App';
});

// 组件内守卫
export default {
  beforeRouteEnter(to, from, next) {
    // 不能访问this
    next(vm => {
      // 通过vm访问组件实例
    });
  },
  beforeRouteLeave(to, from) {
    // 可以访问this
    if (this.hasUnsavedChanges) {
      return confirm('有未保存的更改，确定离开？');
    }
  }
};
